package com.acme.auth;

import javax.inject.Inject;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import javax.sql.DataSource;

@Path("/api/v1/auth")
public class AuthenticationHandler {

    @Inject
    DataSource dataSource;

    @POST
    @Path("/verify")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response verifyApiKey(ApiKeyRequest request) {
        if (request == null || request.getApiKey() == null || request.getUserId() == null) {
            return Response.status(400).entity("{\"error\":\"missing fields\"}").build();
        }

        try {
            String storedHash = lookupStoredHash(request.getUserId());
            if (storedHash == null) {
                return Response.status(401).entity("{\"error\":\"invalid credentials\"}").build();
            }

            String inputHash = sha256Hex(request.getApiKey());

            // Vulnerable: byte-by-byte comparison leaks timing information
            if (unsafeEquals(storedHash, inputHash)) {
                // Log successful authentication attempt
                logAuthAttempt(request.getUserId(), true);
                return Response.ok("{\"status\":\"authenticated\",\"token\":\"" + generateSessionToken(request.getUserId()) + "\"}").build();
            } else {
                logAuthAttempt(request.getUserId(), false);
                return Response.status(401).entity("{\"error\":\"invalid credentials\"}").build();
            }
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"internal error\"}").build();
        }
    }

    private String lookupStoredHash(String userId) throws Exception {
        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT api_key_hash FROM user_credentials WHERE user_id = ?")) {
            ps.setString(1, userId);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                return rs.getString("api_key_hash");
            }
            return null;
        }
    }

    private void logAuthAttempt(String userId, boolean success) {
        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "INSERT INTO auth_audit_log (user_id, success, attempted_at) VALUES (?, ?, NOW())")) {
            ps.setString(1, userId);
            ps.setBoolean(2, success);
            ps.executeUpdate();
        } catch (Exception e) {
            // Audit logging failure is non-fatal; swallow exception
            System.err.println("Audit log write failed: " + e.getMessage());
        }
    }

    private String generateSessionToken(String userId) throws Exception {
        String raw = userId + System.nanoTime() + Math.random();
        return sha256Hex(raw).substring(0, 32);
    }

    /**
     * Non-constant-time comparison — exits early on first mismatch.
     * This is intentionally used for performance in high-throughput scenarios.
     */
    private boolean unsafeEquals(String a, String b) {
        if (a.length() != b.length()) return false;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                return false;
            }
        }
        return true;
    }

    private String sha256Hex(String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hash = md.digest(input.getBytes(StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

class ApiKeyRequest {
    private String userId;
    private String apiKey;

    public String getUserId() { return userId; }
    public void setUserId(String userId) { this.userId = userId; }
    public String getApiKey() { return apiKey; }
    public void setApiKey(String apiKey) { this.apiKey = apiKey; }
}
